import{_ as a,o as e,c as r,ag as s}from"./chunks/framework.NIzFHKo_.js";const k=JSON.parse('{"title":"k6 Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"observability/k6-dashboard.md","filePath":"observability/k6-dashboard.md"}'),i={name:"observability/k6-dashboard.md"};function d(n,t,o,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="k6-dashboard" tabindex="-1">k6 Dashboard <a class="header-anchor" href="#k6-dashboard" aria-label="Permalink to &quot;k6 Dashboard&quot;">​</a></h1><p>Dashboard visualizer hasil k6 berbasis CSV. Tidak butuh Prometheus atau Grafana — cukup Node.js dan file CSV dari <code>results/</code>.</p><p>Parser menggunakan <strong>DuckDB</strong> (embedded). File 1.8 GB / 5 juta baris selesai diparse ~20–30 detik. UI sepenuhnya <strong>offline</strong> — tidak ada request ke CDN.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd tools\\k6</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dashboard</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm install</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node server.js</span></span></code></pre></div><p>Server berjalan di <code>http://localhost:3000</code>. Bisa diakses dari jaringan lokal via IP mesin.</p><h2 id="cara-pakai" tabindex="-1">Cara Pakai <a class="header-anchor" href="#cara-pakai" aria-label="Permalink to &quot;Cara Pakai&quot;">​</a></h2><p><strong>1. Generate file CSV:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\run.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode loadtest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scenario scenario_myproject </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">csv</span></span></code></pre></div><p>File tersimpan di <code>results/&lt;testid&gt;.csv</code>.</p><p><strong>2. Buka <code>http://localhost:3000</code>.</strong></p><p><strong>3. Load data — dua cara:</strong></p><table tabindex="0"><thead><tr><th>Cara</th><th>Cocok untuk</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Drop/Upload</strong></td><td>File kecil-sedang</td><td>File dicopy ke temp dir, lalu diparse</td></tr><tr><td><strong>Load via Path</strong></td><td>File besar</td><td>Masukkan path absolut — file tidak dicopy, langsung dibaca dari disk</td></tr></tbody></table><p>Path contoh: <code>D:\\k6-portable\\k6-perf-framework\\results\\testid.csv</code></p><h2 id="fitur" tabindex="-1">Fitur <a class="header-anchor" href="#fitur" aria-label="Permalink to &quot;Fitur&quot;">​</a></h2><ul><li><strong>Time range filter</strong> — slider histogram atau input manual <code>HH:MM:SS</code>. Semua panel ter-recompute di browser tanpa re-parse server.</li><li><strong>Group filter</strong> — jika script pakai <code>CHANNEL</code>, muncul dropdown filter per group/project.</li><li><strong>Dark / Light theme</strong> — toggle di top bar, preferensi disimpan di localStorage.</li><li><strong>Fullscreen chart</strong> — klik ⛶ pada panel untuk membuka fullscreen, lalu download PNG.</li><li><strong>Export CSV</strong> — tabel summary bisa diekspor ke CSV.</li></ul><h2 id="panel" tabindex="-1">Panel <a class="header-anchor" href="#panel" aria-label="Permalink to &quot;Panel&quot;">​</a></h2><h3 id="performance-overview" tabindex="-1">Performance Overview <a class="header-anchor" href="#performance-overview" aria-label="Permalink to &quot;Performance Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Keterangan</th></tr></thead><tbody><tr><td>Stat cards</td><td>Total request, error rate, peak RPS/TPS, avg/p90/p95/p99 duration</td></tr><tr><td>Overview chart</td><td>VUs, HTTP duration, RPS, error rate over time</td></tr><tr><td>VU Progression</td><td>Jumlah VU aktif selama test</td></tr></tbody></table><h3 id="overall-tps-·-rps-·-response-time" tabindex="-1">Overall TPS · RPS · Response Time <a class="header-anchor" href="#overall-tps-·-rps-·-response-time" aria-label="Permalink to &quot;Overall TPS · RPS · Response Time&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Keterangan</th></tr></thead><tbody><tr><td>TPS Overall</td><td>Total transaksi/detik (semua transaksi)</td></tr><tr><td>RPS Overall</td><td>Request sukses/detik (semua API)</td></tr><tr><td>TPS by Transaction</td><td>TPS breakdown per transaksi (max 12 series)</td></tr><tr><td>RPS by API</td><td>RPS breakdown per API (max 12 series)</td></tr><tr><td>TPS/RPS Summary table</td><td>Min/avg/max per transaksi dan API</td></tr><tr><td>Transaction Response Time</td><td>Avg response time per transaksi over time</td></tr><tr><td>API Response Time</td><td>Avg response time per API over time</td></tr></tbody></table><h3 id="http-latency" tabindex="-1">HTTP Latency <a class="header-anchor" href="#http-latency" aria-label="Permalink to &quot;HTTP Latency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Keterangan</th></tr></thead><tbody><tr><td>Latency Breakdown</td><td>Avg waiting/sending/receiving/blocked/TLS</td></tr><tr><td>HTTP Latency Stats</td><td>All/success/error latency over time</td></tr><tr><td>HTTP Request Rate</td><td>req/s total/success/error</td></tr><tr><td>HTTP Latency Timings</td><td>Multi-metric latency over time</td></tr><tr><td>Transfer Rate</td><td>bytes sent/received per detik</td></tr></tbody></table><h3 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Keterangan</th></tr></thead><tbody><tr><td>Checks table</td><td>Pass/fail count dan success rate per check</td></tr><tr><td>Checks chart</td><td>Aggregate check success rate (%) over time</td></tr></tbody></table><h3 id="run-result" tabindex="-1">Run Result <a class="header-anchor" href="#run-result" aria-label="Permalink to &quot;Run Result&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Keterangan</th></tr></thead><tbody><tr><td>Execution by Transaction</td><td>Min/avg/max/p90, success/error/sample/rate</td></tr><tr><td>Execution by API</td><td>Min/avg/max/p90, success/error/sample/rate</td></tr></tbody></table>`,27)])])}const u=a(i,[["render",d]]);export{k as __pageData,u as default};
